"b5aa6defdf8f8572e92f015a2d9d87f4","category":"工程","subcategory":"机械结构","sub_category_id":12},{"id":1327,"title":"火箭发射台","source_hash":"db31acbcc6b57141353778dcbcc32446","category":"工程","subcategory":"模型制作","sub_category_id":9},{"id":1329,"title":"电路串并联","source_hash":"632aef30977ac3af8449efc75d0c7ef5","category":"技术","subcategory":"电子制作","sub_category_id":7}]$taxonomy$::jsonb)
AS x(id integer,title text,source_hash text,category text,subcategory text,sub_category_id integer);
DO $guard$
DECLARE n integer;
BEGIN
 IF (SELECT count(*) FROM video_taxonomy_patch) <> 813 THEN RAISE EXCEPTION 'Unexpected taxonomy patch size'; END IF;
 PERFORM p.id FROM public.projects p JOIN video_taxonomy_patch v ON v.id=p.id ORDER BY p.id FOR UPDATE OF p;
 IF EXISTS (SELECT 1 FROM video_taxonomy_patch v LEFT JOIN public.projects p ON p.id=v.id
   WHERE p.id IS NULL OR md5(jsonb_build_array(p.title,p.description,p.category,p.sub_category_id,p.tags,p.video_url,(select jsonb_agg(jsonb_build_object('title',s.title,'description',s.description) order by s.sort_order,s.id) from public.project_steps s where s.project_id=p.id))::text) IS DISTINCT FROM v.source_hash)
 THEN RAISE EXCEPTION 'Video taxonomy source changed; review again'; END IF;
 IF EXISTS (SELECT 1 FROM video_taxonomy_patch v
   LEFT JOIN public.sub_categories s ON s.id=v.sub_category_id
   LEFT JOIN public.categories c ON c.id=s.category_id
   WHERE v.sub_category_id IS NOT NULL AND (s.id IS NULL OR s.name IS DISTINCT FROM v.subcategory OR c.name IS DISTINCT FROM v.category))
 THEN RAISE EXCEPTION 'Video taxonomy category mapping changed'; END IF;
 UPDATE public.projects p SET category=v.category,sub_category_id=v.sub_category_id,updated_at=now()
 FROM video_taxonomy_patch v WHERE p.id=v.id;
 GET DIAGNOSTICS n = ROW_COUNT;
 IF n <> 813 THEN RAISE EXCEPTION 'Incomplete taxonomy update: %',n; END IF;
 IF EXISTS (SELECT 1 FROM video_taxonomy_patch v JOIN public.projects p ON p.id=v.id
   WHERE p.category IS DISTINCT FROM v.category OR p.sub_category_id IS DISTINCT FROM v.sub_category_id)
 THEN RAISE EXCEPTION 'Video taxonomy update verification failed'; END IF;
END;
$guard$;
COMMIT;
